import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, color, clamp, lessThan, min, sub, uniform } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, Shape, ExtrudeGeometry, PlaneGeometry, DoubleSide } = ctx.THREE;

  // ----- Parameters -----
  const width = 2.6;
  const height = 0.68;
  const radius = 0.08;
  const depth = 0.03; // extrusion depth
  const bevelSize = radius;
  const bevelThickness = depth * 0.5;
  const edgeColorHex = '#ff2a38';
  const edgeBaseIntensity = 1.6;
  const edgeHoverIntensity = 2.2;
  const edgeWidthWorld = 0.015;

  // ----- Shape (rounded rect) -----
  const shape = new Shape();
  shape.moveTo(-width / 2 + radius, -height / 2);
  shape.lineTo(width / 2 - radius, -height / 2);
  shape.quadraticCurveTo(width / 2, -height / 2, width / 2, -height / 2 + radius);
  shape.lineTo(width / 2, height / 2 - radius);
  shape.quadraticCurveTo(width / 2, height / 2, width / 2 - radius, height / 2);
  shape.lineTo(-width / 2 + radius, height / 2);
  shape.quadraticCurveTo(-width / 2, height / 2, -width / 2, height / 2 - radius);
  shape.lineTo(-width / 2, -height / 2 + radius);
  shape.quadraticCurveTo(-width / 2, -height / 2, -width / 2 + radius, -height / 2);

  const extrudeSettings = {
    depth,
    bevelEnabled: true,
    bevelThickness,
    bevelSize,
    bevelSegments: 4,
    steps: 1,
  };
  const geometry = new ExtrudeGeometry(shape, extrudeSettings);

  // ----- Node material (gradient + edge emissive) -----
  // Gradient colors
  const gradC0 = color('#ff4450');
  const gradC1 = color('#ff2a38');
  const gradC2 = color('#c1121f');

  const uvNode = uv();
  const y = uvNode.y;

  const t0 = clamp(y.div(0.55), 0.0, 1.0);
  const mix01 = mix(gradC0, gradC1, t0);
  const t1 = clamp(y.sub(0.55).div(0.45), 0.0, 1.0);
  const finalColor = mix(mix01, gradC2, t1);

  // Edge emissive mask
  const edgeWidthU = edgeWidthWorld / width;
  const edgeWidthV = edgeWidthWorld / height;
  const edgeWidth = Math.min(edgeWidthU, edgeWidthV);
  const edgeDist = min(
    min(uvNode.x, sub(1.0, uvNode.x)),
    min(uvNode.y, sub(1.0, uvNode.y))
  );
  const edgeMask = lessThan(edgeDist, uniform(edgeWidth));

  const edgeIntensity = uniform(edgeBaseIntensity);
  const edgeColor = color(edgeColorHex);
  const emissive = edgeMask.mul(edgeColor).mul(edgeIntensity);

  const material = new MeshStandardNodeMaterial();
  material.colorNode = finalColor;
  material.emissiveNode = emissive;
  material.roughness = 0.5;
  material.metalness = 0.35;
  material.clearcoat = 0.22;
  material.transparent = true;
  material.side = DoubleSide;

  const buttonMesh = new Mesh(geometry, material);
  buttonMesh.castShadow = true;
  buttonMesh.receiveShadow = true;

  // ----- Contact shadow plane -----
  const shadowGeom = new PlaneGeometry(width, height);
  const shadowMat = new MeshStandardNodeMaterial();
  shadowMat.colorNode = vec3(0, 0, 0);
  shadowMat.transparent = true;
  shadowMat.opacityNode = uniform(0.35);
  const shadowMesh = new Mesh(shadowGeom, shadowMat);
  shadowMesh.position.z = -0.08;

  // ----- Text labels -----
  const labelOpts = {
    fontSize: 20,
    color: '#e8ecf2',
    align: 'center',
    letterSpacing: 0.08,
  };
  const captionOpts = {
    fontSize: 9,
    color: '#e8ecf2',
    align: 'center',
    letterSpacing: 0.12,
  };
  const label = ctx.fontAtlas.createText('BEGIN COMMISSION', labelOpts);
  const caption = ctx.fontAtlas.createText('NO DEPOSIT REQUIRED', captionOpts);
  label.position.set(0, 0, 0.001);
  caption.position.set(0, -height / 2 - 0.25, 0.001);

  // ----- Group assembly -----
  const root = new Group();
  root.add(buttonMesh);
  root.add(shadowMesh);
  root.add(label);
  root.add(caption);

  // ----- Interaction handling -----
  const timelines = [];

  // Load animation (weighted settle)
  root.scale.set(1.04, 1.04, 1.04);
  const loadTL = gsap.to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'cubic-bezier(0.165,0.84,0.44,1)',
  });
  timelines.push(loadTL);

  // Hover animation
  function onHoverEnter() {
    gsap.to(root.position, {
      z: 0.06,
      duration: 0.18,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    });
    gsap.to(edgeIntensity, {
      value: edgeHoverIntensity,
      duration: 0.18,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    });
  }

  function onHoverLeave() {
    gsap.to(root.position, {
      z: 0,
      duration: 0.18,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    });
    gsap.to(edgeIntensity, {
      value: edgeBaseIntensity,
      duration: 0.18,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    });
  }

  // Press animation
  function onPressDown() {
    const tl = gsap.to(root.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
    });
    timelines.push(tl);
  }

  function onPressUp() {
    const tl = gsap.to(root.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.12,
      ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
    });
    timelines.push(tl);
  }

  // Attach empty handler map (renderer will forward events)
  root.userData.handlers = {
    pointerenter: onHoverEnter,
    pointerleave: onHoverLeave,
    pointerdown: onPressDown,
    pointerup: onPressUp,
  };

  // ----- Cleanup -----
  root.userData.cleanup = function () {
    timelines.forEach((t) => t.kill());
    geometry.dispose();
    material.dispose();
    shadowGeom.dispose();
    shadowMat.dispose();
    // Font atlas objects are managed by the runtime; no explicit dispose needed.
  };

  return root;
}
